// Package main verifies the workload has working gcp application default credentials with no user setup, however
// they were provided: issued by the runner through workload identity federation (eg compute upload --gcp-auto, the
// workloads generated by the control plane) or the developer's own credentials (eg compute local --gcp-auto).
// see .README.md.
//
// no token is printed, only whether one could be minted.
package main

import (
	"context"
	"log"

	"github.com/egdaemon/eg/runtime/wasi/eg"
	"github.com/egdaemon/eg/runtime/wasi/egenv"
	"github.com/egdaemon/eg/runtime/wasi/shell"
)

func main() {
	log.SetFlags(log.Flags() | log.Lshortfile)
	ctx, done := context.WithTimeout(context.Background(), egenv.TTL())
	defer done()

	err := eg.Perform(
		ctx,
		eg.Build(eg.DefaultModule()),
		eg.Module(
			ctx,
			eg.DefaultModule(),
			shell.Op(
				shell.New("command -v gcloud || sudo sh /usr/share/eg/install/google-cloud.sh"),
				// mints an access token from the credentials of the workload, for federation that exchanges the identity token via sts and impersonation.
				shell.New("gcloud auth application-default print-access-token > /dev/null && echo 'gcp access ok'"),
			),
		),
	)

	if err != nil {
		log.Fatalln(err)
	}
}
